// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _check(uint256 _val, uint256 preExisting) internal {
        try c.SetMinSum(preExisting) {} catch { return; }
        try c.SetMinSum(_val) {} catch { return; }
        uint256 finalMin;
        try c.MinSum() returns (uint256 __r) { finalMin = __r; } catch { return; }
        assertTrue(finalMin == _val);
    }

    function testFuzz_check(uint256 _val, uint256 preExisting) public {
        _check(_val, preExisting);
    }

    receive() external payable {}
}
